"""Build the portable portfolio. Standard-library Python only; edit content.json to update cases."""
from pathlib import Path
from html import escape as esc
import json

ROOT = Path(__file__).resolve().parent
OUT = ROOT / 'docs'
DATA = json.loads((ROOT / 'content.json').read_text())

def e(s): return esc(str(s), quote=True)
def bullets(items): return '<ul>'+''.join('<li>'+e(s)+'</li>' for s in items)+'</ul>'
def flow(items): return '<div class="mini-flow" aria-label="Workflow">'+''.join('<span>'+e(s)+'</span>' for s in items)+'</div>'
def button(url, text, primary=False):
    return f'<a class="button {"primary" if primary else ""}" href="{e(url)}">{e(text)} <span aria-hidden="true">↗</span></a>'
def shell(title, desc, body, home=False):
    navbase = '' if home else '/'
    return f'''<!doctype html><html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{e(title)} | Matthew Koegler</title><meta name="description" content="{e(desc)}">
<meta property="og:type" content="website"><meta property="og:title" content="{e(title)} | Matthew Koegler"><meta property="og:description" content="{e(desc)}">
<meta name="keywords" content="business operations, payments operations, financial operations, revenue reconciliation, residuals, fintech finance, operational reporting">
<meta property="og:site_name" content="Matthew Koegler"><meta property="og:image" content="https://koeglermatt.github.io/assets/residual-revenue-dashboard.png"><meta property="og:image:alt" content="Illustrative residual revenue dashboard — fictional data"><meta name="theme-color" content="#f5f3ed"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/site.css">
</head><body id="top"><a class="skip" href="#main">Skip to content</a>
<header><div class="wrap nav"><a class="brand" href="/"><span class="monogram">MK</span>Matthew Koegler</a><nav aria-label="Main navigation"><a href="{navbase}#projects">Projects</a><a href="{navbase}#samples">Work samples</a><a class="nav-contact" href="{navbase}#contact">Contact ↗</a></nav></div></header>
<main id="main" class="wrap">{body}</main>
<footer class="wrap"><span>Matthew Koegler · Spokane Valley, Washington</span><div><a href="{e(DATA['linkedin'])}" target="_blank" rel="noopener">LinkedIn ↗</a> &nbsp; / &nbsp; <a href="/assets/Matthew-Koegler-Resume.pdf" download>Resume ↓</a> &nbsp; / &nbsp; <a href="#top">Back to top ↑</a></div></footer></body></html>'''

def contact():
    return f'''<section id="contact" class="contact" aria-labelledby="contact-title"><div><div class="eyebrow">Let’s connect</div><h2 id="contact-title">What needs to work better<br>on your team?</h2><p>Open to conversations about business operations, payments, and financial operations roles.</p></div>{button('mailto:'+DATA['email'],'Email Matt')}</section>'''

cards = ''
for i,p in enumerate(DATA['projects'],1):
    cards += f'''<article class="project-card"><div class="card-meta"><span class="number">0{i}</span><span>{e(p['company'])} · {e(p['status'])}</span></div><h3><a href="/projects/{e(p['slug'])}/">{e(p['title'])}</a></h3><p>{e(p['headline'])}</p>{flow(p['flow'])}<a class="text-link" href="/projects/{e(p['slug'])}/">Read the case study <span aria-hidden="true">↗</span></a></article>'''
experience = ''.join(f'''<article class="career"><div><h3>{e(x['company'])}</h3><p class="career-date">{e(x['dates'])}</p></div><div><h4>{e(x['title'])}</h4>{bullets(x['bullets'])}</div></article>''' for x in DATA['experience'])

home = f'''
<section class="hero" aria-labelledby="hero-title"><div><div class="eyebrow">{e(DATA['headline'])}</div><h1 id="hero-title">Make complex<br>operations<br><em>work.</em></h1><p class="specialties">{e(DATA['specialties'])}</p><p class="intro">I’m Matt. I connect people, payment systems, and reporting so teams can resolve discrepancies, run repeatable processes, and trust the numbers behind their decisions.</p><div class="buttons">{button('#projects','View projects',True)}{button('#contact','Contact me')}</div><div class="location">SPOKANE VALLEY, WA · OPEN TO REMOTE OPPORTUNITIES</div></div>
<div class="hero-graphic" role="img" aria-label="My operating approach: understand the business, connect teams and systems, standardize the workflow, validate the numbers, and improve the process."><div class="graphic-head"><span>How I work</span><span>People + systems</span></div><div class="flow"><div class="source-row"><div class="source">Business needs</div><div class="source">People</div><div class="source">Systems & data</div></div><div class="junction"></div><div class="reconcile">Build the workflow.<small>Clear ownership. Traceable data. Useful reporting.</small></div><div class="junction"></div><div class="outputs"><span>Standardize</span><span>Reconcile</span><span>Report & improve</span></div></div><div class="graphic-footer"><span>Payments expertise. Business operations perspective.</span><span aria-hidden="true">✓</span></div></div></section>
<div class="fact-strip" aria-label="Experience snapshot"><div class="fact"><strong>8-month delivery</strong><span>Billing rewrite with end-to-end workflow ownership</span></div><div class="fact"><strong>Up to 5 reporting views</strong><span>The same information adapted for different audiences</span></div><div class="fact"><strong>Nearly a decade</strong><span>At PayTrace, progressing from customers to financial operations</span></div></div>
<section id="projects" aria-labelledby="projects-title"><div class="section-top"><div><div class="eyebrow">Selected projects</div><h2 id="projects-title">From business problem<br>to working process.</h2></div><p>What I owned, how I approached it, and what changed.</p></div><div class="project-cards">{cards}</div></section>
<section id="samples" class="samples" aria-labelledby="samples-title"><div class="section-top"><div><div class="eyebrow">See the work</div><h2 id="samples-title">The detail behind<br>the decision.</h2></div><p>Public work samples show the method. The data does not represent employer performance.</p></div><div class="illustrative"><strong>Illustrative data</strong> — all sample processors, partners, merchants, and figures are fictional. Sample financial figures are not personal achievement metrics.</div>
<figure class="dashboard"><a href="/assets/residual-revenue-dashboard.png" target="_blank" rel="noopener" aria-label="Open illustrative residual revenue dashboard at full size"><img src="/assets/residual-revenue-dashboard.png" width="2048" height="1152" loading="lazy" alt="Illustrative residual revenue dashboard with gross revenue, partner payouts, company net revenue, yield, monthly trends, and reconciliation status."></a><figcaption>Leadership view · Revenue, payout mix, trends, and reconciliation status. <a href="/assets/residual-revenue-dashboard.png" target="_blank" rel="noopener">Open full size ↗</a></figcaption></figure>
<details class="flow-details"><summary>Trace the process from source reporting to leadership decisions <span aria-hidden="true">+</span></summary><div class="illustrative">Illustrative workflow · No employer records, real merchant identifiers, or actual financial figures.</div><a href="/assets/revenue-share-data-flow.png" target="_blank" rel="noopener"><img src="/assets/revenue-share-data-flow.png" width="2048" height="436" loading="lazy" alt="Illustrative data flow: source reports, standardization, mapping and rules, calculations, reconciliation controls, and reporting."></a><p class="small">Open the diagram for a full-size view.</p></details>
<div class="sample-grid"><article><div class="case-label">Executive communication</div><h3>Explain what changed.<br>Make the action clear.</h3><p>A two-page variance memo connects revenue changes, payout mix, reconciliation items, and assigned follow-up.</p><span class="sample-label">Illustrative data · PDF</span>{button('/assets/executive-variance-memo.pdf','Read the memo')}</article><article><div class="case-label">Process & controls</div><h3>Make recurring work<br>easier to hand over.</h3><p>A reconciliation SOP defines source collection, mapping, exception review, approval, and escalation steps.</p><span class="sample-label">Illustrative data · PDF</span>{button('/assets/residual-reconciliation-sop.pdf','View the SOP')}</article></div>
<div class="workbook"><div><h3>Want to inspect the mechanics?</h3><p>The optional workbook contains fictional data, calculation rules, reconciliation, profitability, forecasting, and a portal-audit template.</p><span class="sample-label">Illustrative data · Excel workbook</span></div><a class="button" href="/assets/illustrative-portfolio-model.xlsx" download>Download sample workbook ↓</a></div></section>
<section class="about" id="about" aria-labelledby="about-title"><div><div class="eyebrow">How I think</div><h2 id="about-title">Curious. Intentional.<br>Organized.</h2></div><div><p class="lead">A reliable operation needs more than a correct spreadsheet. It needs clear ownership, consistent inputs, and a process people can follow.</p><p>I started in client services, helping merchants and partners understand their accounts. Moving into finance and operations gave me a view of the systems behind those questions: billing, payments, partner compensation, reconciliation, and reporting.</p><p>That experience shapes where I start. I learn how the work moves, who depends on it, and where the handoffs break. Then I connect the source data, define the rules, reconcile the differences, and build reporting around the decisions people need to make.</p><p>I’m used to presenting the same information several ways for Sales, Finance, partners, and leadership. The numbers should stay consistent; the explanation should fit the audience. I’ve also managed and trained direct reports, documented recurring work, and partnered across teams to deliver system changes.</p><p>My aim is a process the business can keep using: understandable, maintainable, and ready for improvement as the needs change.</p></div></section>
<section class="capabilities" aria-labelledby="skills-title"><div class="eyebrow">Capabilities</div><h2 id="skills-title">Business operations,<br>with financial depth.</h2><div class="cap-grid"><div><h3>Business operations</h3><p>Workflow ownership · Cross-functional delivery · Stakeholder reporting · Training · Process improvement</p></div><div><h3>Payments & finance</h3><p>Billing · AR & AP · ACH & settlement support · Residuals · Partner payouts · Reconciliation · Budget and forecast reviews</p></div><div><h3>Data & systems</h3><p>Excel · Google Sheets · Zoho CRM & Analytics · QuickBooks · Sigma BI · Workday · CaptivateIQ</p></div><div><h3>Process & controls</h3><p>Requirements documentation · Exception analysis · Validation · SOPs · Portal audits · Reporting consistency</p></div></div></section>
<section class="experience" aria-labelledby="experience-title"><div class="section-top"><div><div class="eyebrow">Experience</div><h2 id="experience-title">Built from the work up.</h2></div>{button('/assets/Matthew-Koegler-Resume.pdf','View full resume')}</div>{experience}</section>{contact()}'''
(OUT/'index.html').write_text(shell(DATA['headline'], 'Matthew Koegler connects business operations, payment systems, and financial reporting. Explore billing, revenue-share, and commission-system projects.', home,True))

for p in DATA['projects']:
    body = f'''<article class="case-page"><a class="text-link back" href="/#projects">← All projects</a><div class="eyebrow">{e(p['company'])} · {e(p['category'])}</div><h1>{e(p['title'])}</h1><p class="case-deck">{e(p['headline'])}</p><span class="status">{e(p['status'])}</span>{flow(p['flow'])}<div class="case-grid"><section><h2>Why it mattered</h2><p>{e(p['context'])}</p><h2>The problem</h2><p>{e(p['problem'])}</p><h2>My role</h2><p>{e(p['role'])}</p><h2>The approach</h2><ol>{''.join('<li>'+e(s)+'</li>' for s in p['approach'])}</ol></section><aside><div class="case-outcome"><div class="case-label">What changed</div>{bullets(p['results'])}</div><h2>What I built</h2><p>{e(p['solution'])}</p><h2>Tools & methods</h2><div class="tags">{''.join('<span class="tag">'+e(s)+'</span>' for s in p['tools'])}</div><h2>What I’d do next</h2><p>{e(p['next'])}</p><p class="case-note">{e(p['evidence'])}</p></aside></div>'''
    if p['slug']=='revenue-share-operations':
        body += '''<div class="illustrative"><strong>Illustrative data</strong> — the public samples demonstrate the approach with fictional entities and figures.</div><figure class="dashboard"><a href="/assets/revenue-share-data-flow.png" target="_blank" rel="noopener"><img src="/assets/revenue-share-data-flow.png" width="2048" height="436" alt="Illustrative revenue-share workflow from sources through mapping, calculations, reconciliation, and reporting."></a><figcaption>Illustrative workflow · <a href="/#samples">Explore the dashboard, memo, SOP, and sample workbook ↗</a></figcaption></figure>'''
    body += '</article>'+contact()
    target=OUT/'projects'/p['slug'];target.mkdir(parents=True,exist_ok=True)
    (target/'index.html').write_text(shell(p['title'],p['headline'],body))
(OUT/'site.css').write_text((ROOT/'site.css').read_text())
print('Built homepage and',len(DATA['projects']),'case-study pages.')
